import { describe, test, expect, beforeEach } from 'bun:test';
import { ClaudeEventProcessor } from '../event-processors/claude/ClaudeEventProcessor';
import { PathNormalizationService } from '../services/PathNormalizationService';
import { TestPathNormalizationAdapter, createTestAdapter } from '../adapters/TestPathNormalizationAdapter';
import type { ClaudeHookInput } from '../event-processors/claude/types';
import testFixtures from '../../test-data/claude-test-fixtures.json';

/**
 * End-to-end integration tests for the complete normalization pipeline:
 * Raw Claude Hook → ClaudeEventProcessor → UniversalAgentSessionEvent
 * → PathNormalizationService → RepoNormalizedUniversalAgentSessionEvent
 */
describe('Normalization Pipeline Integration', () => {
  let claudeProcessor: ClaudeEventProcessor;
  let pathService: PathNormalizationService;

  beforeEach(() => {
    claudeProcessor = new ClaudeEventProcessor();

    // Create adapter with repositories matching the test fixtures
    const adapter = createTestAdapter([
      ['/Users/griever/Developer/build-stuff/monorepo/electron-react', {
        root: '/Users/griever/Developer/build-stuff/monorepo/electron-react',
        remoteUrl: 'https://github.com/griever/electron-react.git',
        owner: 'griever',
        repo: 'electron-react'
      }],
      ['/Users/griever/Developer/PrincipleMD/code-city-landing', {
        root: '/Users/griever/Developer/PrincipleMD/code-city-landing',
        remoteUrl: 'https://github.com/PrincipleMD/code-city-landing.git',
        owner: 'PrincipleMD',
        repo: 'code-city-landing'
      }]
    ]);

    pathService = new PathNormalizationService(adapter);
  });

  describe('Complete pipeline flow', () => {
    test('should process PreToolUse Read event through both stages', async () => {
      // Stage 1: Raw Claude event → UniversalAgentSessionEvent
      const rawEvent = testFixtures.claude.preToolUse as ClaudeHookInput;
      const universalEvent = claudeProcessor.normalize(rawEvent);

      // Verify Stage 1 output
      expect(universalEvent.eventType).toBe('pre-tool-use');
      expect(universalEvent.provider).toBe('claude');
      expect(universalEvent.toolName).toBe('Read');
      expect(universalEvent.rawFilePaths).toBeDefined();
      expect(universalEvent.rawFilePaths).toContain(
        '/Users/griever/Developer/build-stuff/monorepo/electron-react/.erb/scripts/delete-source-maps.js'
      );

      // Stage 2: UniversalAgentSessionEvent → RepoNormalizedUniversalAgentSessionEvent
      const normalizedEvent = await pathService.normalizePaths(universalEvent);

      // Verify Stage 2 output
      expect(normalizedEvent.files).toBeDefined();
      expect(normalizedEvent.files).toHaveLength(1);

      const file = normalizedEvent.files![0];
      expect(file.repository).toBeDefined();
      // File is in same repo as working directory, so only has minimal info
      expect(file.repository?.gitRoot).toBeDefined();
      expect(file.repository?.relativePath).toBe('.erb/scripts/delete-source-maps.js');
      expect(file.repository?.repo).toBeUndefined(); // Omitted since in event.repository
      expect(file.displayPath).toBe('.erb/scripts/delete-source-maps.js');

      // Event should have the full repository info
      expect(normalizedEvent.repository).toBeDefined();
      expect(normalizedEvent.repository?.repo).toBe('electron-react');

      // Verify rawFilePaths was removed
      expect(normalizedEvent.rawFilePaths).toBeUndefined();

      // Verify other properties preserved
      expect(normalizedEvent.eventType).toBe('pre-tool-use');
      expect(normalizedEvent.sessionId).toBe('e8a7d70c-f4e1-48a2-93b8-2b471c417043');
      expect(normalizedEvent.toolName).toBe('Read');
    });

    test('should process PostToolUse event with tool response', async () => {
      // Stage 1: Raw Claude event → UniversalAgentSessionEvent
      const rawEvent = testFixtures.claude.postToolUse as ClaudeHookInput;
      const universalEvent = claudeProcessor.normalize(rawEvent);

      // Verify tool output is captured
      expect(universalEvent.eventType).toBe('post-tool-use');
      expect(universalEvent.toolOutput).toBeDefined();
      expect(universalEvent.toolOutput).toHaveProperty('file');

      // Stage 2: Path normalization
      const normalizedEvent = await pathService.normalizePaths(universalEvent);

      // Verify complete normalization
      expect(normalizedEvent.files).toBeDefined();
      expect(normalizedEvent.files![0].repository?.repo).toBeUndefined(); // In event.repository instead
      expect(normalizedEvent.repository?.repo).toBe('electron-react');
      expect(normalizedEvent.toolOutput).toBeDefined(); // Tool output preserved
    });

    test('should process Edit tool event with operation mapping', async () => {
      const rawEvent = testFixtures.claude.tools.edit as ClaudeHookInput;

      // Stage 1
      const universalEvent = claudeProcessor.normalize(rawEvent);
      expect(universalEvent.operation).toBe('edit');
      expect(universalEvent.rawFilePaths).toBeDefined();

      // Stage 2
      const normalizedEvent = await pathService.normalizePaths(universalEvent);
      expect(normalizedEvent.operation).toBe('edit'); // Operation preserved
      expect(normalizedEvent.files).toBeDefined();
    });

    test('should process Grep search tool with multiple file results', async () => {
      // Create a Grep PostToolUse event with multiple file results
      const grepEvent: ClaudeHookInput = {
        session_id: 'test-session',
        transcript_path: '/test/transcript.jsonl',
        cwd: '/Users/griever/Developer/build-stuff/monorepo/electron-react',
        hook_event_name: 'PostToolUse',
        tool_name: 'Grep',
        tool_input: {
          pattern: 'import.*React',
          path: '/Users/griever/Developer/build-stuff/monorepo/electron-react/src'
        },
        tool_response: [
          '/Users/griever/Developer/build-stuff/monorepo/electron-react/src/App.tsx:1:import React from "react"',
          '/Users/griever/Developer/build-stuff/monorepo/electron-react/src/components/Button.tsx:1:import React from "react"',
          '/Users/griever/Developer/build-stuff/monorepo/electron-react/src/index.tsx:1:import React from "react"'
        ].join('\n')
      };

      // Stage 1
      const universalEvent = claudeProcessor.normalize(grepEvent);
      expect(universalEvent.operation).toBe('search');
      expect(universalEvent.rawFilePaths).toContain(
        '/Users/griever/Developer/build-stuff/monorepo/electron-react/src/App.tsx'
      );

      // Stage 2
      const normalizedEvent = await pathService.normalizePaths(universalEvent);

      // Should have 4 files: the search path + 3 result files
      expect(normalizedEvent.files).toHaveLength(4);

      // All files should be in the same repository
      normalizedEvent.files!.forEach(file => {
        expect(file.repository?.repo).toBeUndefined(); // In event.repository instead
        expect(file.repository?.relativePath).toMatch(/^src/);
      });

      // Repository info should be at event level
      expect(normalizedEvent.repository?.repo).toBe('electron-react');

      // Verify the result files are included
      const filePaths = normalizedEvent.files!.map(f => f.repository?.relativePath);
      expect(filePaths).toContain('src/App.tsx');
      expect(filePaths).toContain('src/components/Button.tsx');
      expect(filePaths).toContain('src/index.tsx');
    });

    test('should handle Notification event without file paths', async () => {
      const rawEvent = testFixtures.claude.notification as ClaudeHookInput;

      // Stage 1
      const universalEvent = claudeProcessor.normalize(rawEvent);
      expect(universalEvent.eventType).toBe('notification');
      expect(universalEvent.rawFilePaths).toBeUndefined();
      expect(universalEvent.data?.message).toBe('Claude needs your permission to use Update');

      // Stage 2
      const normalizedEvent = await pathService.normalizePaths(universalEvent);
      expect(normalizedEvent.files).toBeUndefined();
      expect(normalizedEvent.data?.message).toBe('Claude needs your permission to use Update');
    });

    test('should handle Stop event correctly', async () => {
      const rawEvent = testFixtures.claude.stop as ClaudeHookInput;

      // Stage 1
      const universalEvent = claudeProcessor.normalize(rawEvent);
      expect(universalEvent.eventType).toBe('stop');
      expect(universalEvent.data?.stopHookActive).toBe(false);

      // Stage 2
      const normalizedEvent = await pathService.normalizePaths(universalEvent);
      expect(normalizedEvent.eventType).toBe('stop');
      expect(normalizedEvent.data?.stopHookActive).toBe(false);
      expect(normalizedEvent.normalizedWorkingDirectory).toBe(
        '/Users/griever/Developer/PrincipleMD/code-city-landing'
      );
    });

    test('should handle files outside any repository', async () => {
      const rawEvent: ClaudeHookInput = {
        session_id: 'test-session',
        transcript_path: '/tmp/transcript.jsonl',
        cwd: '/tmp',
        hook_event_name: 'PreToolUse',
        tool_name: 'Write',
        tool_input: {
          file_path: '/tmp/test-output.txt',
          content: 'test content'
        }
      };

      // Stage 1
      const universalEvent = claudeProcessor.normalize(rawEvent);
      expect(universalEvent.rawFilePaths).toContain('/tmp/test-output.txt');

      // Stage 2
      const normalizedEvent = await pathService.normalizePaths(universalEvent);
      expect(normalizedEvent.files).toBeDefined();
      expect(normalizedEvent.files![0].repository).toBeUndefined();
      expect(normalizedEvent.files![0].absolutePath).toBe('/tmp/test-output.txt');
      expect(normalizedEvent.files![0].displayPath).toBe('/tmp/test-output.txt');
    });

    test('should handle MCP tool events', async () => {
      if (!testFixtures.claude.edgeCases?.mcpTool) {
        return; // Skip if no MCP tool in fixtures
      }

      const rawEvent = testFixtures.claude.edgeCases.mcpTool as ClaudeHookInput;

      // Stage 1
      const universalEvent = claudeProcessor.normalize(rawEvent);
      expect(universalEvent.toolName).toContain('mcp__');

      // Stage 2
      const normalizedEvent = await pathService.normalizePaths(universalEvent);
      expect(normalizedEvent.toolName).toContain('mcp__');
      // MCP tools may or may not have file paths
    });

    test('should preserve all metadata through both stages', async () => {
      const rawEvent = testFixtures.claude.tools.bash as ClaudeHookInput;
      const timestamp = Date.now();

      // Stage 1
      const universalEvent = claudeProcessor.normalize(rawEvent);

      // Stage 2
      const normalizedEvent = await pathService.normalizePaths(universalEvent);

      // Verify core properties preserved
      expect(normalizedEvent.provider).toBe('claude');
      expect(normalizedEvent.sessionId).toBeDefined();
      expect(normalizedEvent.workingDirectory).toBeDefined();
      expect(normalizedEvent.transcriptPath).toBeDefined();
      expect(normalizedEvent.timestamp).toBeGreaterThan(0);
      expect(normalizedEvent.raw).toBeDefined();
    });
  });

  describe('Error handling and edge cases', () => {
    test('should handle malformed tool_response gracefully', async () => {
      const rawEvent: ClaudeHookInput = {
        session_id: 'test',
        transcript_path: '/test/transcript.jsonl',
        cwd: '/test',
        hook_event_name: 'PostToolUse',
        tool_name: 'Grep',
        tool_input: { pattern: 'test' },
        tool_response: { error: 'No matches found' } // Non-standard response
      };

      // Should not throw
      const universalEvent = claudeProcessor.normalize(rawEvent);
      const normalizedEvent = await pathService.normalizePaths(universalEvent);

      expect(normalizedEvent.eventType).toBe('post-tool-use');
      expect(normalizedEvent.files).toBeUndefined();
    });

    test('should handle relative paths in tool input', async () => {
      const rawEvent: ClaudeHookInput = {
        session_id: 'test',
        transcript_path: '/test/transcript.jsonl',
        cwd: '/Users/griever/Developer/build-stuff/monorepo/electron-react',
        hook_event_name: 'PreToolUse',
        tool_name: 'Read',
        tool_input: {
          file_path: './src/index.tsx'
        }
      };

      // Stage 1
      const universalEvent = claudeProcessor.normalize(rawEvent);
      expect(universalEvent.rawFilePaths).toContain('./src/index.tsx');

      // Stage 2 - should resolve relative path
      const normalizedEvent = await pathService.normalizePaths(universalEvent);
      expect(normalizedEvent.files![0].originalPath).toBe('./src/index.tsx');
      expect(normalizedEvent.files![0].absolutePath).toBe(
        '/Users/griever/Developer/build-stuff/monorepo/electron-react/src/index.tsx'
      );
      expect(normalizedEvent.files![0].repository?.relativePath).toBe('src/index.tsx');
    });
  });
});